import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import * as Sentry from '@sentry/node';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
assert.ok(process.env.SENTRY_DSN, 'the application receives its own project DSN');
Sentry.init({ dsn: process.env.SENTRY_DSN, defaultIntegrations: false });
Sentry.setUser({ id: 'customer-member' });
Sentry.setTag('application', 'customer-workflow');
const eventId = Sentry.captureException(new Error('Customer workflow exception'));
assert.match(eventId, /^[a-f0-9]{32}$/i);
assert.equal(await Sentry.close(5000), true, 'the SDK drains its exception envelope');
writeFileSync('.sentry-event.json', JSON.stringify({ eventId }) + '\n');
await import('./readback.mjs');

