import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
const { eventId } = JSON.parse(readFileSync('.sentry-event.json', 'utf8'));
// https://docs.sentry.io/api/events/retrieve-an-event-for-a-project/
const url = 'https://sentry.io/api/0/projects/' + encodeURIComponent(process.env.SENTRY_ORG) + '/' + encodeURIComponent(process.env.SENTRY_PROJECT) + '/events/' + eventId + '/';
const response = await fetch(url, { headers: { authorization: 'Bearer ' + process.env.SENTRY_AUTH_TOKEN } });
assert.equal(response.status, 200, 'the issued organization token reads its project event');
const event = await response.json();
assert.equal(event.eventID, eventId);
assert.equal(event.user.id, 'customer-member');
assert.ok(event.tags.some(tag => tag.key === 'application' && tag.value === 'customer-workflow'));
const exception = event.entries.find(entry => entry.type === 'exception');
assert.equal(exception.data.values[0].value, 'Customer workflow exception');
assert.ok(exception.data.values[0].stacktrace.frames.length > 0, 'the SDK stack survives ingestion and resume');
console.log(JSON.stringify({ eventId: event.eventID, exception: exception.data.values[0].value, retained: true }));
